package upstream

import (
    "context"
    "fmt"
    "io"
    "net/http"
)

func FetchJSON(ctx context.Context, client *http.Client, url string) ([]byte, error) {
    req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
    if err != nil { return nil, fmt.Errorf("build request: %w", err) }
    req.Header.Set("Accept", "application/json")
    resp, err := client.Do(req)
    if err != nil { return nil, fmt.Errorf("fetch %s: %w", url, err) }
    defer resp.Body.Close()
    if resp.StatusCode != http.StatusOK {
        _, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4<<10))
        return nil, fmt.Errorf("fetch %s: status %d", url, resp.StatusCode)
    }
    body, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
    if err != nil { return nil, fmt.Errorf("read response: %w", err) }
    return body, nil
}

